// A Server Component: no directive needed
export default async function OrdersPage() {
  const user = await requireUser();
  const orders = await findOrders(user.id);

  async function cancelOrder(orderId: string) {
    "use server"; // only this function becomes callable
    const caller = await requireUser(); // check on every call
    await deleteOrderOwnedBy(caller.id, orderId);
  }

  return <OrderList orders={orders} onCancel={cancelOrder} />;
}

