"use client";
import { useTransition } from "react";

type Props = { orderId: string; onCancel: (id: string) => Promise<void> };

export function CancelButton({ orderId, onCancel }: Props) {
  const [isPending, startTransition] = useTransition();
  return (
    <button
      disabled={isPending}
      onClick={() => startTransition(() => onCancel(orderId))}
    >
      {isPending ? "Cancelling…" : "Cancel"}
    </button>
  );
}
